import java.util.ArrayList;
import java.util.List;

public class BankAccount {
    // 1. Private instance variables
    private String accountNumber;
    private String accountHolderName;
    private double balance;
    private String accountType;
    private List<String> transactionHistory;

    // 2. Overloaded constructor 1: default balance
    public BankAccount(String accountNumber, String accountHolderName) {
        this(accountNumber, accountHolderName, 0.0, "CHECKING");
    }

    // 3. Primary canonical constructor with validation
    public BankAccount(String accountNumber, String accountHolderName, double initialDeposit, String accountType) {
        if (accountNumber == null || accountNumber.trim().isEmpty()) {
            throw new IllegalArgumentException("Account number cannot be empty.");
        }
        if (accountHolderName == null || accountHolderName.trim().isEmpty()) {
            throw new IllegalArgumentException("Account holder name cannot be empty.");
        }
        if (initialDeposit < 0.0) {
            throw new IllegalArgumentException("Initial deposit cannot be negative.");
        }
        this.accountNumber = accountNumber.trim();
        this.accountHolderName = accountHolderName.trim();
        this.balance = initialDeposit;
        this.accountType = (accountType != null) ? accountType.toUpperCase() : "CHECKING";
        this.transactionHistory = new ArrayList<>();
        this.transactionHistory.add(String.format("Account opened with balance: $%.2f", initialDeposit));
    }

    // 4. Deposit method
    public boolean deposit(double amount) {
        if (amount <= 0) {
            System.err.println("Deposit amount must be positive.");
            return false;
        }
        this.balance += amount;
        this.transactionHistory.add(String.format("Deposit: +$%.2f (New Balance: $%.2f)", amount, this.balance));
        return true;
    }

    // 5. Withdraw method
    public boolean withdraw(double amount) {
        if (amount <= 0) {
            System.err.println("Withdrawal amount must be positive.");
            return false;
        }
        if (amount > this.balance) {
            System.err.printf("Insufficient funds. Requested $%.2f but balance is $%.2f.%n", amount, this.balance);
            return false;
        }
        this.balance -= amount;
        this.transactionHistory.add(String.format("Withdrawal: -$%.2f (New Balance: $%.2f)", amount, this.balance));
        return true;
    }

    // 6. Inter-account transfer
    public boolean transferTo(BankAccount target, double amount) {
        if (target == null) {
            System.err.println("Transfer target account cannot be null.");
            return false;
        }
        if (target == this) {
            System.err.println("Cannot transfer funds to the same account.");
            return false;
        }
        if (this.withdraw(amount)) {
            target.deposit(amount);
            this.transactionHistory.add(String.format("Transfer to %s: -$%.2f", target.getAccountNumber(), amount));
            target.transactionHistory.add(String.format("Transfer from %s: +$%.2f", this.accountNumber, amount));
            return true;
        }
        return false;
    }

    // 7. Statement output
    public void printStatement() {
        System.out.println("=======================================================");
        System.out.println("                 ACCOUNT STATEMENT                     ");
        System.out.println("=======================================================");
        System.out.printf("Account Number:  %s%n", accountNumber);
        System.out.printf("Holder Name:     %s%n", accountHolderName);
        System.out.printf("Account Type:    %s%n", accountType);
        System.out.printf("Current Balance: $%.2f%n", balance);
        System.out.println("-------------------------------------------------------");
        System.out.println("TRANSACTION HISTORY:");
        for (int i = 0; i < transactionHistory.size(); i++) {
            System.out.printf(" [%d] %s%n", i + 1, transactionHistory.get(i));
        }
        System.out.println("=======================================================\n");
    }

    public String getAccountNumber() { return accountNumber; }
    public String getAccountHolderName() { return accountHolderName; }
    public double getBalance() { return balance; }
    public String getAccountType() { return accountType; }
}

